-- Seed data para competencias específicas de 5to Grado del Nivel Secundario
-- Documento oficial: Adecuación Curricular Nivel Secundario - Segundo Ciclo (5to Grado)

INSERT INTO public.curr_competencias_especificas (nivel, grado, asignatura, bloque, competencia_fundamental, codigo, descriptor) VALUES
-- Lengua Española
('Secundaria', '5to', 'Lengua Española', 'BC1', 'Comunicativa', 'CE-LE1', 'Muestra destrezas lingüísticas al exponer ideas y experiencias en diferentes situaciones de comunicación social, mediante un tipo de texto (funcional o literario) conveniente desde la comprensión y producción oral y escrita, usando medios y recursos diversos.'),
('Secundaria', '5to', 'Lengua Española', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LE2', 'Analiza textos variados a partir de inferencias, demostrando un pensamiento estructurado que le lleva a conclusiones razonables y lógicas en diferentes contextos.'),
('Secundaria', '5to', 'Lengua Española', 'BC2', 'Resolución de Problemas', 'CE-LE3', 'Selecciona textos específicos que apoyan el desarrollo de una investigación científica, siguiendo criterios de relevancia, pertinencia, validez y confiabilidad para la solución de problemas.'),
('Secundaria', '5to', 'Lengua Española', 'BC4', 'Ética y Ciudadana', 'CE-LE4', 'Emplea diversidad de textos de secuencia argumentativa, con los que conoce y cuestiona las prácticas sociales de ciudadanía en el entorno local y nacional, confrontándolas con valores universales.'),
('Secundaria', '5to', 'Lengua Española', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LE7', 'Utiliza textos literarios y de otros tipos, para manifestar sus sentimientos, emociones, inquietudes en la promoción de valores universales y fortalecer la dimensión humanista.'),
('Secundaria', '5to', 'Lengua Española', 'BC3', 'Científica y Tecnológica', 'CE-LE5', 'Divulga a través textos de secuencia expositivo-explicativa hallazgos científicos, sociales y tecnológicos a lo largo del tiempo, para aportar soluciones a problemas de diferentes contextos.'),
('Secundaria', '5to', 'Lengua Española', 'BC3', 'Ambiental y de la Salud', 'CE-LE6', 'Publica informaciones sobre temas relacionados con salud y medioambiente, a través de textos como catálogo, receta, artículos de opinión e instructivos, en el ámbito escolar y comunitario, haciendo uso de herramientas tecnológicas, entre otras.'),

-- Lenguas Extranjeras - Inglés
('Secundaria', '5to', 'Inglés', 'BC1', 'Comunicativa', 'CE-LEI1', 'Se comunica en el idioma inglés oral y escrito de forma sostenida y comprensible y con una estructura básica del discurso en distintas situaciones de comunicación sobre aspectos la vida diaria y a temas que le son familiares o de su interés, en los que presenta información, solicitudes, quejas, contraste de elementos e ideas, sugerencias, narraciones de experiencias y probabilidades.'),
('Secundaria', '5to', 'Inglés', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LEI2', 'Utiliza estructuras lógico-verbales sencillas del discurso para compartir información o ideas, narrar hechos reales o imaginarios, comparar elementos o ideas, y expresar probabilidad y certeza, empleando estrategias de desempeño comunicativo de forma crítica y creativa.'),
('Secundaria', '5to', 'Inglés', 'BC2', 'Resolución de Problemas', 'CE-LEI3', 'Se comunica a través de textos sencillos y de forma sostenida en inglés para describir situaciones o problemas de su entorno de una forma clara y comprensible, compartiendo información relevante, datos, reclamos, sugerencias, y contrastando alternativas frente a las dificultades.'),
('Secundaria', '5to', 'Inglés', 'BC4', 'Ética y Ciudadana', 'CE-LEI4', 'Se comunica con las demás personas con cortesía, asertividad y respeto, valorando las diferencias individuales y la identidad social y cultural propias de la cultura local y de otros países al comunicarse en el idioma inglés de forma oral y escrita.'),
('Secundaria', '5to', 'Inglés', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LEI7', 'Se comunica en el idioma inglés, con cortesía, honestidad y actitud de respeto, al interactuar en situaciones cotidianas en forma sencilla donde comparte experiencias personales, deseos, aspiraciones y planes propios y de otras personas.'),
('Secundaria', '5to', 'Inglés', 'BC3', 'Científica y Tecnológica', 'CE-LEI5', 'Localiza, sistematiza y comparte información e ideas de carácter científico de forma oral y escrita, utilizando de manera comprensible el idioma inglés en distintas situaciones de comunicación presencial, digital o virtual.'),
('Secundaria', '5to', 'Inglés', 'BC3', 'Ambiental y de la Salud', 'CE-LEI6', 'Muestra preferencia por las opciones que impactan positivamente la salud y el medio ambiente al pedir y dar consejos y sugerencias en temas de adquisición de bienes o servicios y consultas médicas, al interactuar en inglés de forma sostenida y comprensible.'),

-- Lenguas Extranjeras - Francés
('Secundaria', '5to', 'Francés', 'BC1', 'Comunicativa', 'CE-LEF1', 'Comprende y expresa ideas, sentimientos y valores culturales en distintas situaciones de comunicación orales y escritas, utilizando el idioma francés de forma breve con la finalidad de describir personas y lugares, dar y pedir información sobre actividades cotidianas y de recreación, hacer prohibiciones e invitaciones y dar órdenes e instrucciones, con relación a necesidades concretas y temas cotidianos.'),
('Secundaria', '5to', 'Francés', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LEF2', 'Interactúa en el idioma francés empleando estrategias de desempeño, el razonamiento lógico y la expresión creativa y crítica, con el propósito de comunicarse de forma clara y efectiva en distintas situaciones concretas de comunicación oral y escrita, empleando frases y oraciones breves y sencillas.'),
('Secundaria', '5to', 'Francés', 'BC2', 'Resolución de Problemas', 'CE-LEF3', 'Se comunica en francés oral y escrito de forma básica, pero comprensible, compartiendo información que permite identificar, describir y abordar necesidades, problemas y situaciones comunes de su entorno inmediato.'),
('Secundaria', '5to', 'Francés', 'BC4', 'Ética y Ciudadana', 'CE-LEF4', 'Se comunica con las demás personas en el idioma francés de forma oral y escrita, en intercambios breves y sencillos, con cortesía, honestidad, asertividad y respeto, siguiendo las normas de convivencia y organización establecidas y reconociendo las diferencias individuales, la identidad sociocultural y de otros países, relativos a rasgos físicos, formas de interactuar, preferencias, puntualidad, lugares de interés, tradiciones y recreación.'),
('Secundaria', '5to', 'Francés', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LEF7', 'Se comunica en el idioma francés con cortesía, asertividad, actitud de respeto, honestidad y aceptación al expresarse sobre sí mismo y las demás personas con el propósito de describir personas, dar órdenes y hacer prohibiciones.'),
('Secundaria', '5to', 'Francés', 'BC3', 'Científica y Tecnológica', 'CE-LEF5', 'Se comunica en el idioma francés de forma personal, digital o virtual, con la finalidad de compartir información, ideas y opiniones sobre asuntos científicos, tecnológicos y de otra índole de su entorno inmediato, en distintas situaciones de comunicación.'),
('Secundaria', '5to', 'Francés', 'BC3', 'Ambiental y de la Salud', 'CE-LEF6', 'Muestra preferencias por actividades cotidianas y opciones que impactan de forma positiva la salud propia y la de otras personas y el medioambiente en distintas situaciones de comunicación, utilizando frases y oraciones breves y sencillas de forma oral y escrita.'),

-- Matemática
('Secundaria', '5to', 'Matemática', 'BC1', 'Comunicativa', 'CE-MAT1', 'Emplea ideas oralmente y por escrito, haciendo uso de la notación apropiada y valorando la potencia de esta en el desarrollo de las propias ideas matemáticas.'),
('Secundaria', '5to', 'Matemática', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-MAT2', 'Juzga la validez de un argumento matemático, haciendo uso de los conocimientos y las reglas de razonamiento lógico.'),
('Secundaria', '5to', 'Matemática', 'BC2', 'Resolución de Problemas', 'CE-MAT3', 'Formula problemas a partir de situaciones dentro y fuera del contexto matemático y busca sus soluciones.'),
('Secundaria', '5to', 'Matemática', 'BC4', 'Ética y Ciudadana', 'CE-MAT4', 'Justifica, respetando e integrando el criterio de las demás personas, soluciones a problemas por medio de sus conocimientos matemáticos.'),
('Secundaria', '5to', 'Matemática', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-MAT7', 'Aplica sus conocimientos matemáticos, mostrando interés en la discusión e interpretación de situaciones de su entorno.'),
('Secundaria', '5to', 'Matemática', 'BC3', 'Científica y Tecnológica', 'CE-MAT5', 'Aplica herramientas tecnológicas para la toma de decisiones frente a determinados problemas dentro y fuera de la matemática.'),
('Secundaria', '5to', 'Matemática', 'BC3', 'Ambiental y de la Salud', 'CE-MAT6', 'Aplica la metodología de resolución de problemas para descomponer y estudiar los problemas relativos a cambio climático y preservación del medioambiente.'),

-- Ciencias Sociales
('Secundaria', '5to', 'Ciencias Sociales', 'BC1', 'Comunicativa', 'CE-CS1', 'Desarrolla análisis críticos de información, utilizando fuentes primarias y secundarias; con la finalidad de establecer comparaciones respaldadas en información verificable y confiable entre eventos sociales, políticos, económicos, históricos, geográficos o culturales.'),
('Secundaria', '5to', 'Ciencias Sociales', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-CS2', 'Contextualiza la relación existente entre los procesos históricos ocurridos en espacios geográficos de la isla de Santo Domingo, mediante el uso de hipótesis; con la finalidad presentar argumentaciones que evidencien su influencia en los cambios económicos, sociales, políticos y culturales del contexto en el que se produjeron.'),
('Secundaria', '5to', 'Ciencias Sociales', 'BC2', 'Resolución de Problemas', 'CE-CS3', 'Comprende la naturaleza y contexto de un problema o situación específica, incluyendo su ubicación temporal y espacial; con la finalidad de identificar sus posibles causas mediante la realización de investigaciones pertinentes que permitan desarrollar estrategias efectivas en garantes de su resolución.'),
('Secundaria', '5to', 'Ciencias Sociales', 'BC4', 'Ética y Ciudadana', 'CE-CS4', 'Diseña propuestas de investigación que involucren activamente a diversos actores en la promoción de los valores culturales e interculturales garantes de la construcción ciudadana y de la convivencia democrática; con la finalidad de propiciar el respeto por la Constitución y los derechos humanos.'),
('Secundaria', '5to', 'Ciencias Sociales', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-CS7', 'Aplica propuestas que promuevan el respeto hacia su persona y la sociedad; con la finalidad de fomentar una convivencia armoniosa implicando el valor de la dignidad, los derechos y las necesidades de cada individuo sin discriminación o menosprecio hacia los demás.'),
('Secundaria', '5to', 'Ciencias Sociales', 'BC3', 'Científica y Tecnológica', 'CE-CS5', 'Integra el análisis de información científica sobre teorías relacionadas a fenómenos naturales y sociales, utilizando la tecnología, con la finalidad de ofrecer explicaciones claras y concisas de las informaciones obtenidas.'),
('Secundaria', '5to', 'Ciencias Sociales', 'BC3', 'Ambiental y de la Salud', 'CE-CS6', 'Explica situaciones que ponen en riesgo su salud y los recursos naturales, con la finalidad de promover el cuidado de su entorno y estilos de vida saludables.'),

-- Ciencias de la Naturaleza – Química
('Secundaria', '5to', 'Ciencias de la Naturaleza', 'BC1', 'Comunicativa', 'CE-CN1', 'Se comunica utilizando el lenguaje científico y tecnológico fundamental de la química que implica ideas, leyes, modelos y procesos.'),
('Secundaria', '5to', 'Ciencias de la Naturaleza', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-CN2', 'Ofrece explicaciones y estrategias científicas y tecnológicas a problemas y fenómenos naturales relacionados con los fundamentos de la química.'),
('Secundaria', '5to', 'Ciencias de la Naturaleza', 'BC2', 'Resolución de Problemas', 'CE-CN3', 'Aplica diversos procedimientos científicos y tecnológicos para solucionar problemas o dar respuestas a fenómenos naturales relacionados con los fundamentos de la química.'),
('Secundaria', '5to', 'Ciencias de la Naturaleza', 'BC4', 'Ética y Ciudadana', 'CE-CN4', 'Analiza críticamente la naturaleza y filosofía de la química, ingenierías y las tecnologías, sus aportes, alcance del desarrollo tecnológico en nuestra sociedad y la ética en la investigación.'),
('Secundaria', '5to', 'Ciencias de la Naturaleza', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-CN7', 'Gestiona actitudes intelectuales, emocionales y conductuales proactivas al desarrollo de su proyección personal y profesional desde la química e ingenierías.'),
('Secundaria', '5to', 'Ciencias de la Naturaleza', 'BC3', 'Científica y Tecnológica', 'CE-CN5', 'Se cuestiona e identifica problemas y situaciones, a la vez que construye una explicación utilizando conceptos, modelos, leyes, teorías y procesos fundamentales de la química y las ingenierías.'),
('Secundaria', '5to', 'Ciencias de la Naturaleza', 'BC3', 'Ambiental y de la Salud', 'CE-CN6', 'Asume y actúa con responsabilidad crítica y autónoma para un desarrollo sostenible, cuidado ambiental y su salud, basadas en las ideas y teorías de la química.'),

-- Educación Artística
('Secundaria', '5to', 'Educación Artística', 'BC1', 'Comunicativa', 'CE-EA1', 'Usa adecuadamente técnicas y lenguajes artísticos en la comunicación de vivencias personales y problemáticas comunitarias.'),
('Secundaria', '5to', 'Educación Artística', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-EA2', 'Analiza críticamente la pertinencia de técnicas, recursos y procesos creativos, al plantear ideas, propuestas y proyectos.'),
('Secundaria', '5to', 'Educación Artística', 'BC2', 'Resolución de Problemas', 'CE-EA3', 'Realiza propuestas creativas y análisis crítico a partir de los resultados de sus investigaciones artísticas.'),
('Secundaria', '5to', 'Educación Artística', 'BC4', 'Ética y Ciudadana', 'CE-EA4', 'Genera proyectos artísticos que fomenten la tolerancia y convivencia pacífica.'),
('Secundaria', '5to', 'Educación Artística', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-EA7', 'Actúa con asertividad ante situaciones conflictivas, respetando las opiniones contrarias a las suyas, promoviendo el diálogo y mostrando control emocional.'),
('Secundaria', '5to', 'Educación Artística', 'BC3', 'Científica y Tecnológica', 'CE-EA5', 'Analiza el uso de los recursos tecnológicos y científicos en la creación artística en diferentes épocas.'),
('Secundaria', '5to', 'Educación Artística', 'BC3', 'Ambiental y de la Salud', 'CE-EA6', 'Usa el poder comunicativo de las artes y sus manifestaciones, incentivando el desarrollo de conciencia ecológica y el cuidado de la salud.'),

-- Educación Física
('Secundaria', '5to', 'Educación Física', 'BC1', 'Comunicativa', 'CE-EF1', 'Utiliza sus posibilidades de movimiento en su acción motriz, a fin de expresar su estado de ánimo, emociones y sentimientos.'),
('Secundaria', '5to', 'Educación Física', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-EF2', 'Utiliza su percepción y apreciación de la variación de patrones y relaciones temporales en diversos entornos, con el fin de crear cambios en su acción motriz a partir de la noción de su esquema corporal.'),
('Secundaria', '5to', 'Educación Física', 'BC2', 'Resolución de Problemas', 'CE-EF3', 'Relaciona las reglas y los elementos técnicos deportivos con situaciones de la vida cotidiana, a fin de alcanzar los niveles adecuados de eficacia motora progresiva.'),
('Secundaria', '5to', 'Educación Física', 'BC4', 'Ética y Ciudadana', 'CE-EF4', 'Realiza acciones motrices diversas con el grupo respetando las reglas del juego, con el objeto de establecer relaciones de cooperación y/u oposición, teniendo en cuenta las diferencias individuales para el disfrute de las actividades físicas.'),
('Secundaria', '5to', 'Educación Física', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-EF7', 'Utiliza sus habilidades motrices y capacidades corporales y motrices en el logro de metas y en la realización de actividades complejas y secuenciadas, mostrando satisfacción y bienestar en actividades colaborativas de juego.'),
('Secundaria', '5to', 'Educación Física', 'BC3', 'Científica y Tecnológica', 'CE-EF5', 'Ejecuta los cambios necesarios en la aplicación de la normativa, técnicas e implementos que utiliza en las actividades de juego, a partir del reconocimiento de las características y condiciones del terreno donde se realiza y del uso de las herramientas adecuadas.'),
('Secundaria', '5to', 'Educación Física', 'BC3', 'Ambiental y de la Salud', 'CE-EF6', 'Valora los cambios físicos de su cuerpo e introduce acciones complejas para elevar la calidad en su eficiencia motora, adoptando un estilo de vida saludable en consonancia con el cuidado del medioambiente.'),

-- Formación Integral Humana y Religiosa
('Secundaria', '5to', 'Formación Integral Humana y Religiosa', 'BC1', 'Comunicativa', 'CE-FIHR1', 'Analiza el hecho religioso y las enseñanzas de Jesús de Nazaret en el Evangelio, con la finalidad de fomentar el respeto y el diálogo entre las diferentes confesiones cristianas.'),
('Secundaria', '5to', 'Formación Integral Humana y Religiosa', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-FIHR2', 'Aplica las enseñanzas de personajes del Antiguo y del Nuevo Testamento, con la finalidad de dirigir su vida mediante la vivencia de valores en diferentes contextos.'),
('Secundaria', '5to', 'Formación Integral Humana y Religiosa', 'BC2', 'Resolución de Problemas', 'CE-FIHR3', 'Plantea alternativas de solución a situaciones sociales que afectan a la persona, la familia, la escuela y la comunidad, tomando en cuenta las enseñanzas de Jesús de Nazaret, con la finalidad de promover relaciones armoniosas en diferentes contextos.'),
('Secundaria', '5to', 'Formación Integral Humana y Religiosa', 'BC4', 'Ética y Ciudadana', 'CE-FIHR4', 'Analiza los valores y el papel del trabajo en el desarrollo de los pueblos como continuación de la obra creadora de Dios, a fin de reconocer la importancia del trabajo para su vida y la sociedad.'),
('Secundaria', '5to', 'Formación Integral Humana y Religiosa', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-FIHR7', 'Asume la propuesta de Jesús como un estilo de vida que da sentido a las personas y a sus relaciones, con la finalidad de fomentar valores en sus proyectos de vida y en sus relaciones.'),
('Secundaria', '5to', 'Formación Integral Humana y Religiosa', 'BC3', 'Científica y Tecnológica', 'CE-FIHR5', 'Formula juicios éticos sobre el impacto de las ciencias y las tecnologías en la persona, la familia y la cultura, con la finalidad de asumir valores que protejan la vida en el uso de los avances tecnológicos que se dan en la sociedad.'),
('Secundaria', '5to', 'Formación Integral Humana y Religiosa', 'BC3', 'Ambiental y de la Salud', 'CE-FIHR6', 'Establece criterios éticos en la relación con el entorno natural creado por Dios, con la finalidad de crear conciencia y promoción del cuidado y protección de la naturaleza como casa común.')
ON CONFLICT (nivel, grado, asignatura, competencia_fundamental) 
DO UPDATE SET 
    codigo = EXCLUDED.codigo,
    descriptor = EXCLUDED.descriptor,
    bloque = EXCLUDED.bloque,
    updated_at = NOW();
